"use client";

import NeonSignIn from "@/components/neon-sign-in";
import { useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import { Activity, ArrowDownLeft, ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, Building2, CalendarDays, Check, CheckCheck, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Copy, CreditCard, Download, Eye, FileCheck2, FileText, Fence, House, LayoutDashboard, Leaf, LogOut, Mail, MapPin, Menu, MessageCircle, MoreHorizontal, Newspaper, Phone, Plus, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Tag, Trees, Upload, UserRound, UserRoundPlus, UsersRound, Wallet, X, type LucideIcon } from "lucide-react";
import { createDemo, currency, displayDate, decidePayment, PERIOD, previewInvoices, remaining, settlement, submitPayment, total, uid, type Account, type Demo, type Fee, type Invoice, type Payment, type Post, type Request, type Unit } from "@/lib/demo";

import { activeRoles, allowedViews, assignmentStatus, ROLE_LABELS, TENANT_ID } from "@/lib/access";
import { AccessPreview, DEMO_ACCESS_TIME, jakartaTime, RoleManagement } from "@/components/role-management";

import { AdminPaymentForm, ReminderTemplate, WaterBillForm, MessagePreview } from "@/components/billing-management";
import { BillingScopePicker } from "@/components/billing-scope";
import { scopedUnitIds, type BillingScope } from "@/lib/billing-scope";
import { InvoiceItemStatus, PaymentAllocationHistory, PaymentReview, ResidentSelfAssessment } from "@/components/payment-assessment";
import { OccupancyForm, OccupancyHistory, ResidentContactDetails, ResidentContactForm } from "@/components/resident-management";
import { ResidentBills } from "@/components/resident-bills";
import { portalPosts, residentModalAllowed, residentPortal, residentView, setResidentWhatsAppPreference } from "@/lib/resident-portal";
import { isRentalUnit, matchesHousingStatus, residentContacts } from "@/lib/residents";
import { InvoiceDownload } from "@/components/finance-management";
import { BillingOverview, InvoiceKindChooser, type BillingIntent } from "@/components/invoice-management";
import { CashLedger, WhatsAppTemplates } from "@/components/finance-management";
import { cashSummary, withFinancials } from "@/lib/finance";
import { renderMessage } from "@/lib/communications";
import { readNewsImage } from "@/lib/news-image";
import { reviewPayment, withMeteredBilling, periodLabel, waterOverview, billingOverview } from "@/lib/billing";
import { ClusterManagement } from "@/components/cluster-management";
import { addUnit, validateFeeScope, withManagedClusters } from "@/lib/clusters";

type Mode = "admin" | "resident" | "public" | "login";
type ModalSpec = { type: string; id?: string; kind?: Request["kind"]; period?: string; scope?: BillingScope; intent?: BillingIntent; billKind?: "dues" | "water" } | null;
type Actions = { data: Demo; save: (data: Demo) => void; open: (modal: NonNullable<ModalSpec>) => void; go: (view: string) => void; notify: (message: string) => void };
const requestLabels: Record<string, string> = { submitted: "Diajukan", under_review: "Sedang diproses", needs_revision: "Perlu perbaikan", approved: "Disetujui", issued: "Surat terbit", resolved: "Selesai", acknowledged: "Diketahui petugas" };
const paymentLabels: Record<string, string> = { pending: "Menunggu verifikasi", verified: "Terverifikasi", rejected: "Ditolak" };
const adminNav: { group: string; items: { id: string; label: string; icon: LucideIcon }[] }[] = [
  { group: "UTAMA", items: [{ id: "dashboard", label: "Ringkasan", icon: LayoutDashboard }, { id: "units", label: "Warga dan unit", icon: Building2 }] },
  { group: "KEUANGAN", items: [{ id: "invoices", label: "Tagihan", icon: FileText }, { id: "payments", label: "Pembayaran", icon: Wallet }, { id: "reports", label: "Laporan keuangan", icon: FileCheck2 }, { id: "cash", label: "Transaksi kas", icon: Wallet }, { id: "templates", label: "Template WhatsApp", icon: MessageCircle }, { id: "fees", label: "Pengaturan biaya", icon: SlidersHorizontal }] },
  { group: "LINGKUNGAN", items: [{ id: "news", label: "Berita dan kegiatan", icon: Newspaper }, { id: "services", label: "Layanan warga", icon: MessageCircle }] },
  { group: "PENGELOLAAN", items: [{ id: "accounts", label: "Akun pengguna", icon: UsersRound }, { id: "roles", label: "Peran dan masa jabatan", icon: ShieldCheck }, { id: "settings", label: "Pengaturan", icon: Settings2 }] },
];
const residentNav = [{ id: "home", label: "Beranda", icon: House }, { id: "invoices", label: "Tagihan", icon: FileText }, { id: "news", label: "Berita", icon: Newspaper }, { id: "services", label: "Layanan", icon: MessageCircle }, { id: "account", label: "Akun", icon: UserRound }];
const titleMap: Record<string, string> = { dashboard: "Ringkasan", units: "Warga dan unit", invoices: "Tagihan", payments: "Pembayaran", fees: "Pengaturan biaya", news: "Berita dan kegiatan", services: "Layanan warga", accounts: "Akun pengguna", reports: "Laporan keuangan", cash: "Transaksi kas", templates: "Template WhatsApp", settings: "Pengaturan", roles: "Peran dan masa jabatan", home: "Beranda", account: "Akun saya", unit: "Unit saya" };

function Logo({ small = false }: { small?: boolean }) { return <span className={`logo ${small ? "small" : ""}`}><span className="logo-icon"><House size={22} strokeWidth={2.2} /><span /></span>{!small && <span>proomahan<span className="logo-dot">.</span></span>}</span>; }
function Badge({ children, tone }: { children: ReactNode; tone?: string }) {
  const text = typeof children === "string" ? children : "";
  const inferred = /Lunas|Terverifikasi|Selesai|terbit|Aktif|Diketahui|Disetujui|Terhuni/.test(text) ? "green" : /Menunggu|Sebagian|diproses|Diajukan/.test(text) ? "amber" : /Ditolak|Belum|perbaikan/.test(text) ? "red" : "gray";
  return <span className={`badge ${tone || inferred}`}><span className="badge-dot" />{children}</span>;
}
function Button({ children, onClick, secondary = false, small = false, type = "button", disabled = false, danger = false }: { children: ReactNode; onClick?: () => void; secondary?: boolean; small?: boolean; type?: "button" | "submit"; disabled?: boolean; danger?: boolean }) { return <button type={type} disabled={disabled} onClick={onClick} className={`button ${secondary ? "secondary" : "primary"} ${small ? "compact" : ""} ${danger ? "danger" : ""}`}>{children}</button>; }
function Empty({ title = "Belum ada data", detail = "Data yang sesuai akan ditampilkan di sini.", children }: { title?: string; detail?: string; children?: ReactNode }) { return <div className="empty"><span className="empty-icon"><FileText size={25} /></span><h3>{title}</h3><p>{detail}</p>{children}</div>; }
function Heading({ eyebrow, title, subtitle, children }: { eyebrow?: string; title: string; subtitle: string; children?: ReactNode }) { return <div className="page-heading"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{subtitle}</p></div><div className="heading-actions">{children}</div></div>; }
function Person({ name, sub, index = 0 }: { name: string; sub?: string; index?: number }) { return <span className="person"><span className={`avatar tone-${index % 4}`}>{name.split(" ").slice(0, 2).map(n => n[0]).join("")}</span><span><strong>{name}</strong>{sub && <small>{sub}</small>}</span></span>; }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function FooterNote() { return <div className="footer-note"><span>Proomahan <span>·</span> D&apos;Park City</span><span>Lingkungan tertata, warga nyaman.</span></div>; }

export default function Prototype() {
  const [data, setData] = useState<Demo>(createDemo);
  const [ready, setReady] = useState(false);
  const [mode, setMode] = useState<Mode>("admin");
  const [view, setView] = useState("dashboard");
  const [modal, setModal] = useState<ModalSpec>(null);
  const [toast, setToast] = useState("");
  const [menu, setMenu] = useState(false);
  const menuTrigger = useRef<HTMLButtonElement>(null);
  const sidebar = useRef<HTMLElement>(null);
  const [search, setSearch] = useState("");
  const [adminId, setAdminId] = useState("admin");
  const [accessTime, setAccessTime] = useState(DEMO_ACCESS_TIME);
  const [billingPeriod, setBillingPeriod] = useState("2026-11");
  useEffect(() => {
    try { const saved = JSON.parse(localStorage.getItem("proomahan-prototype-v1") || "null"); if (saved && [1, 2, 3, 4, 5].includes(saved.version) && ["units", "fees", "invoices", "payments", "requests", "posts", "accounts"].every(k => Array.isArray(saved[k]))) {
      if ([2, 3, 4, 5].includes(saved.version) && Array.isArray(saved.assignments) && Array.isArray(saved.roleEvents)) setData(withFinancials(withMeteredBilling(withManagedClusters(saved))));
      else if (saved.version === 1) { const baseline = createDemo(); setData(withFinancials(withMeteredBilling(withManagedClusters({ ...saved, version: 3, accounts: saved.accounts.map((account: Account) => ({ ...account, resident: account.id !== "admin" })), assignments: baseline.assignments.filter(a => saved.accounts.some((account: Account) => account.id === a.userId)), roleEvents: [] })))); setToast("Data contoh sebelumnya dipertahankan. Akses pengurus kini memakai penetapan masa jabatan; tinjau kembali di menu Peran."); }
    } } catch { /* A corrupt demo snapshot falls back to the example dataset. */ }
    const query = new URLSearchParams(window.location.search);
    const initial = query.get("mode");
    if (["admin", "resident", "public", "login"].includes(initial || "")) { setMode(initial as Mode); const nextView = initial === "resident" ? residentView(query.get("view")) : query.get("view") === "water" ? "invoices" : query.get("view") || "dashboard"; setView(nextView); if (initial === "resident" && query.get("view") && query.get("view") !== nextView) window.history.replaceState({}, "", `?mode=resident&view=${nextView}`); }
    setReady(true);
  }, []);
  useEffect(() => { if (ready) { try { localStorage.setItem("proomahan-prototype-v1", JSON.stringify(data)); } catch { setToast("Perubahan masih ada pada sesi ini, tetapi penyimpanan browser penuh atau tidak tersedia. Kurangi gambar sebelum memuat ulang."); } } }, [data, ready]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(""), 5000); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => {
    if (!menu || !window.matchMedia("(max-width: 760px)").matches) return;
    const previousOverflow = document.body.style.overflow; document.body.style.overflow = "hidden";
    const buttons = () => [...(sidebar.current?.querySelectorAll<HTMLButtonElement>("button:not(:disabled)") || [])];
    buttons()[0]?.focus();
    const keyboard = (event: KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); setMenu(false); }
      if (event.key !== "Tab") return;
      const controls = buttons(); const first = controls[0]; const last = controls.at(-1);
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
    };
    document.addEventListener("keydown", keyboard);
    return () => { document.body.style.overflow = previousOverflow; document.removeEventListener("keydown", keyboard); if (menuTrigger.current?.getClientRects().length) menuTrigger.current.focus(); };
  }, [menu]);
  const go = (view: string) => { const next = mode === "resident" ? residentView(view) : view; setView(next); setSearch(""); setMenu(false); window.scrollTo({ top: 0, behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" }); window.history.replaceState({}, "", `?mode=${mode}&view=${next}`); };
  const switchMode = (next: Mode) => { setMode(next); setView(next === "resident" ? "home" : "dashboard"); setMenu(false); setSearch(""); setModal(null); window.history.replaceState({}, "", `?mode=${next}`); window.scrollTo(0, 0); };
  const portal = residentPortal(data);
  const residentName = portal.account?.name || "Akun warga";
  const residentInitials = residentName.split(" ").slice(0, 2).map(word => word[0]).join("");
  const actions: Actions = { data, save: setData, open: setModal, go, notify: setToast };
  const pending = data.payments.filter(p => p.status === "pending").length;
  const accessAt = jakartaTime(accessTime);
  const views = allowedViews(data, adminId, TENANT_ID, accessAt);
  const roles = activeRoles(data, adminId, TENANT_ID, accessAt);
  const adminAccount = data.accounts.find(a => a.id === adminId);
  const adminName = adminAccount?.name || "Akun contoh";
  const adminInitials = adminName.split(" ").slice(0, 2).map(n => n[0]).join("");
  const adminLabel = roles.map(r => ROLE_LABELS[r]).join(" · ") || "Tanpa akses pengurus";
  const nav = mode === "resident" ? [{ group: "RUANG WARGA", items: residentNav }] : adminNav.map(group => ({ ...group, items: group.items.filter(item => views.includes(item.id)) })).filter(group => group.items.length);
  const canView = mode !== "admin" || views.includes(view);
  if (!ready) return <div className="prototype-loading" role="status" aria-live="polite"><Logo /><p>Menyiapkan halaman lingkungan…</p></div>;
  return <>
    <a className="skip-link" href="#main-content">Lewati ke konten utama</a>
    <div className="prototype-bar"><span><span className="live-dot" />Pratinjau interaktif <span className="prototype-detail">· Seluruh data merupakan contoh</span></span><div className="mode-switch" aria-label="Pilih tampilan pratinjau">{([{ id: "public", label: "Publik" }, { id: "admin", label: "Admin" }, { id: "resident", label: "Warga" }] as const).map(m => <button key={m.id} aria-pressed={mode === m.id} onClick={() => switchMode(m.id)}>{m.label}</button>)}</div></div>
    {mode === "public" ? <PublicView {...actions} enter={() => window.location.assign("/sign-in")} /> : mode === "login" ? <NeonSignIn /> : <div className={`app-shell ${mode === "resident" ? "resident-shell" : ""}`}>
      {menu && <button className="sidebar-scrim" aria-label="Tutup navigasi" onClick={() => setMenu(false)} />}
      <aside ref={sidebar} aria-label="Navigasi utama" className={`sidebar ${menu ? "is-open" : ""}`}>
        <button className="brand-button" onClick={() => go(mode === "resident" ? "home" : "dashboard")}><Logo /></button>
        <div className="neighborhood"><span className="neighborhood-icon"><Trees size={21} /></span><div><strong>D&apos;Park City</strong><small>Lingkungan kita</small></div><ChevronDown size={15} /></div>
        <nav>{nav.map(group => <div className="nav-group" key={group.group}><div className="nav-label">{group.group}</div>{group.items.map(item => <button key={item.id} onClick={() => go(item.id)} className={`nav-item ${view === item.id ? "active" : ""}`} aria-current={view === item.id ? "page" : undefined}><item.icon size={19} /><span>{item.label}</span>{item.id === "payments" && pending > 0 && <span className="nav-count">{pending}</span>}</button>)}</div>)}</nav>
        <div className="sidebar-bottom"><div className="help-card"><span><Leaf size={19} /></span><strong>Lingkungan lebih baik,<br />dimulai dari kita.</strong><p>Kelola bersama, tumbuh bersama.</p></div><button className="profile-button" onClick={() => mode === "resident" ? go("account") : setToast(`${adminName} · ${adminLabel}`)}><span className="avatar teal">{mode === "resident" ? residentInitials : adminInitials}</span><span><strong>{mode === "resident" ? residentName : adminName}</strong><small>{mode === "resident" ? `Warga · ${portal.unit?.cluster || "—"} / ${portal.unit?.number || "Belum terhubung"}` : adminLabel}</small></span><MoreHorizontal size={17} /></button></div>
      </aside>
      <div className="workspace"><header className="topbar"><div className="breadcrumb"><button ref={menuTrigger} className="icon-button menu-button" aria-label="Buka navigasi" aria-expanded={menu} onClick={() => setMenu(true)}><Menu size={22} /></button><span>D&apos;Park City</span><ChevronRight size={14} /><strong>{titleMap[view] || "Ringkasan"}</strong></div><div className="topbar-actions">{mode === "admin" && views.includes("units") && <form className="header-search" onSubmit={e => { e.preventDefault(); setView("units"); }}><Search size={17} /><input aria-label="Cari unit atau warga" placeholder="Cari unit atau warga..." value={search} onChange={e => setSearch(e.target.value)} /></form>}{(mode === "resident" || roles.includes("super_admin")) && <button className="icon-button notification-button" aria-label="Lihat pemberitahuan" onClick={() => setModal({ type: "notifications" })}><Bell size={20} /><i /></button>}<span className="header-divider" /><span className="avatar small-avatar">{mode === "resident" ? residentInitials : adminInitials}</span></div></header>
        <main id="main-content" className="main-content" tabIndex={-1}>{mode === "admin" && <AccessPreview data={data} userId={adminId} time={accessTime} change={(id, time) => { setAdminId(id); setAccessTime(time); setModal(null); setMenu(false); const next = allowedViews(data, id, TENANT_ID, jakartaTime(time)); setView(next.includes(view) ? view : next[0] || "no-access"); }} />}{mode === "admin" ? canView ? <>
          {view === "dashboard" && <Dashboard {...actions} />}
          {view === "units" && <UnitsView {...actions} search={search} />}
          {view === "invoices" && <BillingOverview data={data} period={billingPeriod} changePeriod={setBillingPeriod} create={period => setModal({ type: "createBilling", period })} invoiceAction={(id, intent) => { const pending = data.payments.find(payment => payment.invoiceId === id && payment.status === "pending"); setModal(intent === "payment" ? pending ? { type: "review", id: pending.id } : { type: "adminPayment", id } : { type: intent === "reminder" ? "reminder" : "invoice", id }); }} detail={(id, period, intent, billKind) => { const row = billingOverview(data, period).rows.find(row => row.unit.id === id); const invoices = billKind === "dues" ? row?.duesInvoices : billKind === "water" ? row?.waterInvoices : undefined; setModal(invoices?.length === 1 ? { type: "invoice", id: invoices[0].id } : { type: "billingDetail", id, period, intent, billKind }); }} />}
          {view === "fees" && <FeesView {...actions} />}
          {view === "reports" && <CashLedger key="finance-overview" initialTab="overview" data={data} save={setData} actorId={adminId} at={accessAt} notify={setToast} message={(id, period) => setModal(id ? { type: "expenseMessage", id } : { type: "cashMessage", id: period })} />}
          {view === "cash" && <CashLedger key="finance-transactions" data={data} save={setData} actorId={adminId} at={accessAt} notify={setToast} message={(id, period) => setModal(id ? { type: "expenseMessage", id } : { type: "cashMessage", id: period })} />}
          {view === "templates" && <WhatsAppTemplates data={data} save={setData} actorId={adminId} at={accessAt} notify={setToast} />}
          {view === "payments" && <PaymentsView {...actions} />}
          {view === "accounts" && <AccountsView {...actions} at={accessAt} actorId={adminId} />}
          {view === "news" && <NewsView {...actions} admin />}
          {view === "services" && <ServicesView {...actions} admin />}
          {view === "settings" && <SettingsView {...actions} />}
          {view === "roles" && <RoleManagement data={data} save={setData} actorId={adminId} at={accessAt} notify={setToast} />}
        </> : <Empty title="Tidak ada akses untuk halaman ini" detail="Masa jabatan mungkin telah berakhir, akses dicabut, atau peran tidak mencakup halaman ini. Akses warga tetap mengikuti akun dan hubungan hunian." >{nav[0]?.items[0] && <Button onClick={() => go(nav[0].items[0].id)}>Buka halaman yang diizinkan</Button>}<Button secondary onClick={() => switchMode("resident")}>Lihat contoh portal warga</Button></Empty> : <>
          {view === "home" && <ResidentHome {...actions} />}
          {view === "invoices" && <ResidentBills data={data} detail={id => setModal({ type: "invoice", id })} contact={() => setModal({ type: "contacts" })} />}
          {view === "news" && <NewsView {...actions} />}
          {view === "services" && <ServicesView {...actions} />}
          {view === "account" && <ResidentAccount {...actions} signout={() => switchMode("login")} />}
          {view === "unit" && <ResidentUnitView {...actions} />}
        </>}<FooterNote /></main>
      </div>
      {mode === "resident" && <nav className="mobile-bottom" aria-label="Navigasi warga">{residentNav.map(item => <button className={view === item.id ? "active" : ""} aria-current={view === item.id ? "page" : undefined} key={item.id} onClick={() => go(item.id)}><item.icon size={21} /><span>{item.label}</span></button>)}</nav>}
    </div>}
    {modal && <ModalContent key={`${modal.type}-${modal.id || ""}-${modal.kind || ""}`} spec={modal} close={() => setModal(null)} {...actions} resident={mode === "resident"} publicView={mode === "public" || mode === "login"} actorId={adminId} at={accessAt} onPeriodChange={setBillingPeriod} />}
    {toast && <div className="toast" role="status"><CheckCircle2 size={20} /><span>{toast}</span><button aria-label="Tutup notifikasi" onClick={() => setToast("")}><X size={16} /></button></div>}
  </>;
}

function Dashboard(a: Actions) {
  const latestPost = portalPosts(a.data, "admin")[0];
  const current = a.data.invoices.filter(i => i.period === PERIOD);
  const collected = current.reduce((sum, i) => sum + i.paid, 0);
  const outstanding = current.reduce((sum, i) => sum + remaining(i), 0);
  const pending = a.data.payments.filter(p => p.status === "pending");
  const occupied = a.data.units.filter(u => u.occupied).length;
  const rate = Math.round(collected / Math.max(current.reduce((s, i) => s + total(i), 0), 1) * 100);
  const [point, setPoint] = useState(6);
  const months = ["Mei", "Jun", "Jul", "Agu", "Sep", "Okt", "Nov"];
  const amounts = [6800000, 7400000, 7050000, 8150000, 7800000, 8700000, collected];
  return <>
    <Heading title="Selamat datang, Nadia" subtitle="Ini kabar lingkungan D'Park City hari ini."><span className="date-chip"><CalendarDays size={16} />Sabtu, 7 November 2026</span></Heading>
    <div className="welcome-strip"><div><span className="strip-icon"><Sparkles size={20} /></span><span><strong>Semua kebutuhan lingkungan, lebih tertata.</strong><small>Pantau iuran, kelola warga, dan tindak lanjuti layanan dari satu tempat.</small></span></div><button onClick={() => a.open({ type: "createBilling", period: "2026-12" })}>Buat tagihan bulanan <ArrowRight size={16} /></button></div>
    <div className="stats-grid">
      {[{ label: "Penerimaan terverifikasi", value: currency(collected), icon: Wallet, foot: `${rate}% dari tagihan bulan ini`, cls: "teal" }, { label: "Sisa tagihan", value: currency(outstanding), icon: FileText, foot: `${current.filter(i => remaining(i) > 0).length} tagihan belum lunas`, cls: "orange" }, { label: "Menunggu verifikasi", value: String(pending.length).padStart(2, "0"), icon: Clock3, foot: "Pembayaran perlu ditinjau", cls: "blue" }, { label: "Unit terhuni", value: `${occupied}`, icon: House, foot: `dari ${a.data.units.length} unit · ${a.data.units.length - occupied} unit kosong`, cls: "purple" }].map((stat, index) => <button className="stat-card" key={stat.label} onClick={() => a.go(index === 2 ? "payments" : index === 3 ? "units" : "invoices")}><div className="stat-top"><span>{stat.label}</span><span className={`stat-icon ${stat.cls}`}><stat.icon size={19} /></span></div><strong className="stat-value">{stat.value}</strong><span className="stat-foot">{index === 0 && <span className="tiny-dot" />}{stat.foot}<ArrowUpRight size={13} /></span></button>)}
    </div>
    <div className="dashboard-middle"><section className="panel chart-panel"><div className="panel-heading"><div><h2>Penerimaan iuran</h2><p>Ringkasan pembayaran yang sudah diverifikasi</p></div><span className="subtle-chip"><CalendarDays size={14} />Mei – Nov 2026</span></div><div className="chart-value"><strong>{currency(amounts[point])}</strong><span>{months[point]} 2026 <span className="green-text">· Terverifikasi</span></span></div><div className="bar-chart" aria-label="Grafik penerimaan contoh Mei sampai November 2026"><div className="chart-grid"><span>12 jt</span><span>8 jt</span><span>4 jt</span><span>0</span></div><div className="chart-bars">{months.map((month, i) => <button className={`chart-column ${point === i ? "selected" : ""}`} key={month} title={`${month}: ${currency(amounts[i])}`} onClick={() => setPoint(i)} aria-label={`${month} 2026: ${currency(amounts[i])}`}><span className="bar-track"><span style={{ height: `${amounts[i] / 12600000 * 100}%` }} /></span><span>{month}</span></button>)}</div></div><div className="chart-legend"><span><i />Penerimaan terverifikasi</span><small>Data historis ilustratif</small></div></section>
      <section className="panel attention-panel"><div className="panel-heading"><div><h2>Perlu perhatian</h2><p>Hal yang menunggu tindak lanjut</p></div><span className="round-icon"><Activity size={17} /></span></div><div className="attention-list">{[{ icon: Wallet, title: "Verifikasi pembayaran", desc: "Cocokkan bukti dan penerimaan", count: pending.length, view: "payments", cls: "amber" }, { icon: FileCheck2, title: "Pengajuan surat", desc: "Tinjau kebutuhan administrasi", count: a.data.requests.filter(r => r.kind === "letter" && r.status !== "issued").length, view: "services", cls: "blue" }, { icon: MessageCircle, title: "Permintaan layanan", desc: "Tindak lanjuti laporan warga", count: a.data.requests.filter(r => r.kind === "report" && r.status !== "resolved").length, view: "services", cls: "teal" }].map(item => <button key={item.title} onClick={() => a.go(item.view)}><span className={`attention-icon ${item.cls}`}><item.icon size={20} /></span><span className="attention-copy"><strong>{item.title}</strong><small>{item.desc}</small></span><span className="attention-count">{item.count}</span><ChevronRight size={15} /></button>)}</div><div className="occupancy-summary"><div><span>Keterhunian lingkungan</span><strong>{Math.round(occupied / a.data.units.length * 100)}%</strong></div><div className="progress-track"><span style={{ width: `${occupied / a.data.units.length * 100}%` }} /></div><small><span className="tiny-dot" />{occupied} terhuni <span className="neutral-dot" />{a.data.units.length - occupied} kosong</small></div></section></div>
    <section className="panel"><div className="panel-heading"><div><h2>Pembayaran terbaru</h2><p>Tinjau pembayaran warga yang menunggu verifikasi</p></div><button className="text-button" onClick={() => a.go("payments")}>Lihat semua <ArrowRight size={15} /></button></div><PaymentTable {...a} payments={pending.slice(0, 3)} /></section>
    <div className="dashboard-bottom"><div className="news-inline"><span className="news-mini-art"><Trees size={33} /></span><div><span className="eyebrow">KABAR LINGKUNGAN</span><strong>{latestPost?.title || "Belum ada kabar lingkungan"}</strong><small>{latestPost ? `${displayDate(latestPost.date)} · ${latestPost.category}` : "Terbitkan informasi terbaru untuk warga."}</small></div><button className="icon-button" aria-label="Baca kabar lingkungan" onClick={() => latestPost ? a.open({ type: "post", id: latestPost.id }) : a.go("news")}><ArrowUpRight size={20} /></button></div><button className="quick-contact" onClick={() => a.open({ type: "contacts" })}><ShieldCheck size={23} /><span><strong>Butuh bantuan petugas?</strong><small>Temukan kontak pengurus dan keamanan.</small></span><ArrowRight size={18} /></button></div>
  </>;
}

function UnitsView(a: Actions & { search: string }) {
  const [query, setQuery] = useState(""); const [cluster, setCluster] = useState(""); const [status, setStatus] = useState("Semua status"); const [page, setPage] = useState(0);
  const filtered = a.data.units.filter(u => `${u.number} ${u.occupant} ${u.owner} ${u.ownerPhone || ""} ${u.occupantPhone || ""}`.toLowerCase().includes((a.search || query).toLowerCase()) && (!cluster || u.cluster === a.data.clusters.find(c => c.id === cluster)?.name) && matchesHousingStatus(u, status));
  const currentPage = Math.min(page, Math.max(0, Math.ceil(filtered.length / 8) - 1));
  return <><Heading title="Warga dan unit" subtitle="Kenali penghuni, pemilik, dan status setiap unit di lingkungan Anda."><Button secondary onClick={() => a.open({ type: "clusters" })}><Building2 size={17} />Kelola klaster</Button><Button secondary onClick={() => downloadCSV(a.data.units)}><Download size={16} />Ekspor data</Button><Button disabled={!a.data.clusters.some(c => !c.archived)} onClick={() => a.open({ type: "addUnit" })}><Plus size={17} />Tambah unit</Button></Heading><div className="small-stat-row"><span><strong>{a.data.units.length}</strong> total unit</span><span><i className="tiny-dot" /><strong>{a.data.units.filter(u => u.occupied).length}</strong> terhuni</span><span><i className="neutral-dot" /><strong>{a.data.units.filter(u => !u.occupied).length}</strong> kosong</span></div><section className="panel"><div className="table-toolbar"><div className="input-search"><Search size={17} /><input aria-label="Cari di daftar unit" placeholder="Cari nomor unit atau nama warga..." value={query} onChange={e => { setQuery(e.target.value); setPage(0); }} /></div><div className="toolbar-filters"><select aria-label="Filter klaster" value={cluster} onChange={e => { setCluster(e.target.value); setPage(0); }}><option value="">Semua klaster</option>{a.data.clusters.map(c => <option key={c.id} value={c.id}>{c.name}{c.archived ? " (diarsipkan)" : ""}</option>)}</select><select aria-label="Filter keterhunian" value={status} onChange={e => { setStatus(e.target.value); setPage(0); }}><option>Semua status</option><option>Terhuni</option><option>Kosong</option><option>Rumah sewa</option><option>Sewa tersedia</option><option>Sewa terhuni</option></select></div></div><div className="table-scroll"><table><thead><tr><th>Unit / klaster</th><th>Pemilik</th><th>Penghuni utama</th><th>Status hunian</th><th>Tipe hunian</th><th /></tr></thead><tbody>{filtered.slice(currentPage * 8, currentPage * 8 + 8).map((u, i) => <tr key={u.id}><td><span className="unit-cell"><span className="unit-icon"><House size={16} /></span><span><strong>{u.number}</strong><small>{u.cluster}</small></span></span></td><td>{u.owner}<small className="resident-phone">{u.ownerPhone || "Telepon belum diisi"}</small></td><td>{u.occupied ? <Person name={u.occupant} sub={u.occupantPhone || "Telepon belum diisi"} index={i} /> : <span className="muted">Belum ada penghuni</span>}</td><td><Badge>{u.occupied ? "Terhuni" : "Kosong"}</Badge></td><td>{isRentalUnit(u) ? u.occupied ? "Rumah sewa · Terhuni" : "Rumah sewa · Tersedia" : u.occupied ? u.tenure : "—"}</td><td><button className="table-action" onClick={() => a.open({ type: "unit", id: u.id })}>Detail <ChevronRight size={14} /></button><button className="table-action resident-occupancy-action" onClick={() => a.open({ type: "residentContacts", id: u.id })}><UserRound size={14} />Edit data</button><button className="table-action resident-occupancy-action" onClick={() => a.open({ type: "occupancy", id: u.id })}><UsersRound size={14} />{u.occupied ? "Check-out" : "Check-in"}</button></td></tr>)}</tbody></table></div>{!filtered.length && <Empty title="Unit tidak ditemukan" detail="Coba kata kunci atau filter yang berbeda." />}<div className="pagination"><span>Menampilkan {filtered.length ? currentPage * 8 + 1 : 0}–{Math.min(currentPage * 8 + 8, filtered.length)} dari {filtered.length} unit</span><div><button aria-label="Halaman sebelumnya" disabled={currentPage === 0} onClick={() => setPage(currentPage - 1)}><ChevronLeft size={16} /></button><span>{currentPage + 1}</span><button aria-label="Halaman berikutnya" disabled={(currentPage + 1) * 8 >= filtered.length} onClick={() => setPage(currentPage + 1)}><ChevronRight size={16} /></button></div></div></section></>;
}

function downloadCSV(units: Unit[]) { const quote = (s: string) => `"${s.replaceAll('"', '""')}"`; const csv = "\ufeffUnit,Klaster,Pemilik,Telepon pemilik,Penghuni,Telepon penghuni,Status\n" + units.map(u => [u.id, u.cluster, u.owner, u.ownerPhone || "", u.occupant, u.occupantPhone || "", u.occupied ? "Terhuni" : "Kosong"].map(quote).join(",")).join("\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); link.download = "unit-dpark-city-contoh.csv"; link.click(); URL.revokeObjectURL(link.href); }

function UnitDetails(a: Actions & { unit: Unit; resident?: boolean }) {
  const [tab, setTab] = useState("Ringkasan");
  return <><div className="unit-detail-hero"><span className="large-unit-icon"><House size={34} /></span><div><span className="eyebrow">KLASTER {a.unit.cluster.toUpperCase()}</span><h2>Unit {a.unit.number}</h2><p>D&apos;Park City <span>·</span> {a.unit.tenure}</p></div><Badge>{a.unit.occupied ? "Terhuni" : "Kosong"}</Badge></div>{!a.resident && <div className="resident-detail-actions"><Button secondary onClick={() => a.open({ type: "residentContacts", id: a.unit.id })}><Phone size={16} />Edit data warga</Button><Button onClick={() => a.open({ type: "occupancy", id: a.unit.id })}><UsersRound size={16} />{a.unit.occupied ? "Check-out" : "Check-in"}</Button></div>}<div className="tabs" role="group" aria-label="Informasi unit">{["Ringkasan", "Penghuni", "Riwayat", "Tagihan"].map(t => <button key={t} aria-pressed={tab === t} onClick={() => setTab(t)} className={tab === t ? "active" : ""}>{t}</button>)}</div><div className="detail-content">{tab === "Ringkasan" && <><div className="detail-grid"><Detail label="Nomor unit" value={a.unit.number} /><Detail label="Klaster" value={a.unit.cluster} /><Detail label="Pemilik utama" value={a.unit.owner} /><Detail label="Penghuni utama" value={a.unit.occupant || "Belum ada penghuni"} /><Detail label="Dihuni sejak" value={a.unit.occupied ? displayDate(a.unit.since) : "—"} /><Detail label="Status rumah sewa" value={isRentalUnit(a.unit) ? a.unit.occupied ? "Rumah sewa · Terhuni" : "Rumah sewa · Tersedia" : "Bukan rumah sewa"} /></div><ResidentContactDetails unit={a.unit} resident={a.resident} viewerName={residentPortal(a.data).account?.name} /><div className="info-note"><ShieldCheck size={18} />Tautan membuka penyimpanan dokumen di tab baru. Hak akses dokumen mengikuti pengaturan Google Drive atau layanan penyimpanan.</div></>}{tab === "Penghuni" && (a.unit.occupied ? <><ResidentContactDetails unit={a.unit} resident={a.resident} viewerName={residentPortal(a.data).account?.name} /><hr /><p className="muted">Data anggota keluarga dapat dikelola pengurus sesuai dokumen yang disetujui.</p></> : <Empty title="Unit belum dihuni" />)}{tab === "Riwayat" && <OccupancyHistory unit={a.unit} resident={a.resident} viewerName={residentPortal(a.data).account?.name} />}{tab === "Tagihan" && <div className="simple-list">{(a.resident ? residentPortal(a.data).invoices : a.data.invoices.filter(i => i.unitId === a.unit.id)).map(i => <button key={i.id} onClick={() => a.open({ type: "invoice", id: i.id })}><span><strong>{i.period}</strong><small>{i.id}</small></span><span><strong>{currency(remaining(i))}</strong><Badge>{settlement(i)}</Badge></span><ChevronRight size={17} /></button>)}</div>}</div></>;
}
function Detail({ label, value }: { label: string; value: string }) { return <div className="detail-pair"><span>{label}</span><strong>{value}</strong></div>; }


function PaymentTable(a: Actions & { payments: Payment[] }) {
  return <div className="table-scroll payment-table" tabIndex={0} role="region" aria-label="Daftar pembayaran"><table><thead><tr><th>Warga / unit</th><th>Nominal</th><th>Metode</th><th>Tanggal</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>{a.payments.map((payment, index) => { const invoice = a.data.invoices.find(invoice => invoice.id === payment.invoiceId); return <tr key={payment.id}><td><Person name={invoice?.person || "Warga"} sub={`Unit ${invoice?.unitNumber || invoice?.unitId || "—"}`} index={index} /></td><td data-label="Nominal"><strong>{currency(payment.amount)}</strong></td><td data-label="Metode"><span className="method-label"><Wallet size={14} />{payment.method}</span></td><td data-label="Tanggal">{displayDate(payment.date)}</td><td><Badge>{paymentLabels[payment.status]}</Badge></td><td><button className="table-action" disabled={!invoice} onClick={() => a.open({ type: "review", id: payment.id })}>{payment.status === "pending" ? "Tinjau" : "Lihat rincian"}<ChevronRight size={14} /></button></td></tr>; })}</tbody></table>{!a.payments.length && <Empty title="Belum ada pembayaran dengan status ini" detail="Konfirmasi pembayaran akan tampil di sini." />}</div>;
}

function PaymentsView(a: Actions) { const [status, setStatus] = useState("pending"); return <><Heading title="Pembayaran warga" subtitle="Cocokkan bukti transfer atau penerimaan tunai sebelum memverifikasi." /><section className="panel"><div className="table-toolbar"><div className="tabs compact-tabs" role="group" aria-label="Status pembayaran">{Object.entries(paymentLabels).map(([key, label]) => <button key={key} className={status === key ? "active" : ""} aria-pressed={status === key} onClick={() => setStatus(key)}>{label}<span className="tab-count">{a.data.payments.filter(p => p.status === key).length}</span></button>)}</div></div><PaymentTable {...a} payments={a.data.payments.filter(p => p.status === status)} /></section><div className="info-note"><ShieldCheck size={18} />Pembayaran dapat diajukan warga atau dicatat langsung oleh pengurus. Status lunas mengikuti nominal yang telah diverifikasi.</div></>; }

function FeesView(a: Actions) { return <><Heading title="Pengaturan biaya" subtitle="Tentukan item, nominal, dan aturan iuran sesuai kebutuhan lingkungan."><Button secondary onClick={() => a.go("invoices")}>Kelola tagihan</Button><Button onClick={() => a.open({ type: "fee" })}><Plus size={17} />Tambah item biaya</Button></Heading><div className="section-note"><span className="round-icon"><SlidersHorizontal size={20} /></span><div><strong>Biaya yang mengikuti kebutuhan lingkungan.</strong><p>Item dan nominal dapat diubah kapan saja. Tagihan yang sudah terbit tetap menggunakan rincian sebelumnya.</p></div></div><div className="fee-grid">{a.data.fees.filter(f => f.id !== "water" && f.itemId !== "water").map((fee, index) => { const Icon = [UsersRound, Leaf, ShieldCheck, Wallet][index % 4]; return <section className={`panel fee-card ${!fee.active ? "fee-inactive" : ""}`} key={fee.id}><div className="fee-header"><span className={`fee-icon tone-${index % 4}`}><Icon size={23} /></span><Badge tone={fee.active ? "green" : "gray"}>{fee.active ? "Aktif" : "Diarsipkan"}</Badge></div><div><span className="eyebrow">{fee.category}</span><h2>{fee.name}</h2><strong className="fee-amount">{currency(fee.amount)}<small> / {fee.frequency === "Bulanan" ? "bulan" : "satu kali"}</small></strong></div><dl><div><dt>Berlaku untuk</dt><dd>{fee.scope}</dd></div><div><dt>Ditagihkan ke</dt><dd>{fee.payer}</dd></div><div><dt>Unit kosong</dt><dd>{fee.vacancy}</dd></div></dl><div className="fee-actions"><Button secondary small onClick={() => a.open({ type: "fee", id: fee.id })}><Settings2 size={14} />Ubah pengaturan</Button><button className="text-button" onClick={() => a.open({ type: "feeOverride", id: fee.id })}>Tarif khusus</button><button className="text-button muted" onClick={() => { a.save({ ...a.data, fees: a.data.fees.map(f => f.id === fee.id ? { ...f, active: !f.active } : f) }); a.notify(fee.active ? "Item diarsipkan. Tagihan yang sudah terbit tidak berubah." : "Item biaya diaktifkan kembali."); }}>{fee.active ? "Arsipkan" : "Aktifkan"}</button></div></section>; })}<button className="add-fee-card" onClick={() => a.open({ type: "fee" })}><span><Plus size={25} /></span><strong>Tambah item biaya</strong><p>Iuran baru, kebutuhan baru.<br />Atur sesuai kesepakatan warga.</p></button></div><div className="info-note"><FileCheck2 size={18} />Gunakan pratinjau tagihan untuk memeriksa nominal dan penanggung jawab sebelum menerbitkan.</div></>; }

function AccountsView(a: Actions & { at: string; actorId: string }) { const visibleAccounts = a.data.accounts.filter(account => activeRoles(a.data, a.actorId, TENANT_ID, a.at).includes("super_admin") || !a.data.assignments.some(role => role.userId === account.id && (role.role === "super_admin" || ["Aktif", "Terjadwal"].includes(assignmentStatus(role, a.at))))); return <><Heading title="Akun pengguna" subtitle="Buat akun, tentukan akses, dan bantu warga mengelola kata sandi."><Button onClick={() => a.open({ type: "account" })}><UserRoundPlus size={17} />Buat akun</Button></Heading><section className="panel"><div className="panel-heading"><div><h2>Akun lingkungan</h2><p>{visibleAccounts.length} akun terdaftar · Persetujuan dilakukan oleh administrator</p></div><span className="subtle-chip"><ShieldCheck size={14} />Akses terkelola</span></div><div className="table-scroll"><table><thead><tr><th>Nama pengguna</th><th>Unit</th><th>Peran</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>{visibleAccounts.map((account, n) => <tr key={account.id}><td><Person name={account.name} sub={account.contact} index={n} /></td><td>{account.unit}</td><td>{[...(account.resident ? ["Warga"] : []), ...activeRoles(a.data, account.id, TENANT_ID, a.at).map(r => ROLE_LABELS[r])].join(" · ") || "Tidak ada peran aktif"}</td><td><Badge tone={account.active ? "green" : "gray"}>{account.active ? "Aktif" : "Nonaktif"}</Badge></td><td><div className="row-actions"><button className="table-action" onClick={() => a.open({ type: "resetPassword", id: account.id })}>Atur ulang sandi</button>{account.id !== "admin" && <button className="text-button muted" onClick={() => { a.save({ ...a.data, accounts: a.data.accounts.map(u => u.id === account.id ? { ...u, active: !u.active } : u) }); a.notify(account.active ? "Akun contoh dinonaktifkan." : "Akun contoh diaktifkan."); }}>{account.active ? "Nonaktifkan" : "Aktifkan"}</button>}</div></td></tr>)}</tbody></table></div></section></>; }

function PostPicture({ post }: { post: Post }) { return post.image ? <img className="post-image" src={post.image} alt={post.title} /> : <Landscape type={post.art} />; }

function Landscape({ type = "garden", hero = false }: { type?: string; hero?: boolean }) { return <div className={`landscape ${type} ${hero ? "hero-landscape" : ""}`} aria-hidden="true"><div className="sun" /><div className="landscape-cloud cloud-one" /><div className="landscape-cloud cloud-two" /><div className="landscape-hill hill-one" /><div className="landscape-hill hill-two" /><div className="park-path" /><div className="illustrated-house house-one"><div className="roof" /><div className="house-wall"><i /><i /><b /></div></div><div className="illustrated-house house-two"><div className="roof" /><div className="house-wall"><i /><i /><b /></div></div><div className="park-tree tree-one"><Trees /></div><div className="park-tree tree-two"><Trees /></div><div className="park-tree tree-three"><Trees /></div><div className="landscape-tag"><Leaf size={13} />D&apos;Park City</div></div>; }
function NewsView(a: Actions & { admin?: boolean }) { const [filter, setFilter] = useState("Semua"); const posts = portalPosts(a.data, a.admin ? "admin" : residentPortal(a.data).account ? "resident" : "public").filter(p => filter === "Semua" || p.category === filter); return <><Heading title="Kabar dari lingkungan kita" subtitle="Informasi terbaru, kegiatan bersama, dan cerita D'Park City.">{a.admin && <Button onClick={() => a.open({ type: "addPost" })}><Plus size={16} />Tulis berita</Button>}</Heading><div className="tabs news-tabs" role="group" aria-label="Kategori berita">{["Semua", "Kegiatan warga", "Pengumuman", "Agenda lingkungan"].map(f => <button className={filter === f ? "active" : ""} aria-pressed={filter === f} onClick={() => setFilter(f)} key={f}>{f}</button>)}</div><div className="news-grid">{posts.map(post => <button className="news-card" key={post.id} onClick={() => a.open({ type: "post", id: post.id })}><PostPicture post={post} /><div className="news-card-copy"><span className="news-category">{post.category}</span><h2>{post.title}</h2><p>{post.body.slice(0, 105)}{post.body.length > 105 ? "…" : ""}</p><div><span>{displayDate(post.date)}</span><ArrowUpRight size={18} /></div></div></button>)}</div>{!posts.length && <Empty title="Belum ada berita dalam kategori ini" />}</>; }

function ServicesView(a: Actions & { admin?: boolean }) {
  const [tab, setTab] = useState<Request["kind"]>("letter");
  const portal = residentPortal(a.data);
  const mine = a.admin ? a.data.requests : portal.requests;
  const labels = { letter: "Surat warga", report: "Permintaan layanan", guest: "Laporan tamu" };
  return <><Heading title={a.admin ? "Layanan warga" : "Ada yang bisa kami bantu?"} subtitle={a.admin ? "Tindak lanjuti kebutuhan warga dan pantau perkembangannya." : "Ajukan kebutuhan administrasi, sampaikan laporan, atau hubungi pengurus."}>{a.admin && <Button secondary onClick={() => a.open({ type: "contacts" })}><Phone size={16} />Kontak layanan</Button>}</Heading>{!a.admin && !portal.canViewUnit && <div className="info-note">Pengajuan baru tersedia setelah hubungan hunian diperbarui. Hubungi pengurus melalui kartu kontak di bawah.</div>}{!a.admin && <div className="service-grid">{[{ kind: "letter", icon: FileCheck2, title: "Ajukan surat", desc: "Urus administrasi tanpa bolak-balik." }, { kind: "report", icon: MessageCircle, title: "Permintaan layanan", desc: "Sampaikan kebutuhan lingkungan." }, { kind: "guest", icon: UserRoundPlus, title: "Laporkan tamu", desc: "Beri tahu petugas tentang kunjungan." }, { kind: "contacts", icon: Phone, title: "Kontak pengurus", desc: "Temukan bantuan yang Anda butuhkan." }].map(s => <button key={s.kind} className="service-card" disabled={s.kind !== "contacts" && !portal.canViewUnit} onClick={() => s.kind === "contacts" ? a.open({ type: "contacts" }) : a.open({ type: "requestForm", kind: s.kind as Request["kind"] })}><span className="service-icon"><s.icon size={24} /></span><h3>{s.title}</h3><p>{s.desc}</p><ArrowUpRight size={17} /></button>)}</div>}<section className="panel"><div className="panel-heading"><div><h2>{a.admin ? "Antrean layanan" : "Pengajuan saya"}</h2><p>{a.admin ? "Pilih pengajuan untuk meninjau dan memperbarui status" : "Pantau setiap proses, dari pengajuan sampai selesai"}</p></div></div><div className="tabs service-tabs" role="group" aria-label="Jenis pengajuan">{Object.entries(labels).map(([key, label]) => <button key={key} className={tab === key ? "active" : ""} aria-pressed={tab === key} onClick={() => setTab(key as Request["kind"])}>{label}<span className="tab-count">{mine.filter(r => r.kind === key).length}</span></button>)}</div><div className="simple-list">{mine.filter(r => r.kind === tab).map(r => <button key={r.id} onClick={() => a.open({ type: "request", id: r.id })}><span className="request-icon">{r.kind === "letter" ? <FileText size={21} /> : r.kind === "guest" ? <UsersRound size={21} /> : <MessageCircle size={21} />}</span><span><strong>{r.title}</strong><small>{r.id} · {a.admin ? `${r.person} · ${r.unitId} · ` : ""}{r.date}</small></span><Badge>{requestLabels[r.status]}</Badge><ChevronRight size={17} /></button>)}</div>{!mine.some(r => r.kind === tab) && <Empty title="Belum ada pengajuan" detail="Pengajuan Anda beserta perkembangannya akan muncul di sini." />}</section>{!a.admin && <button className="gate-contact" onClick={() => a.open({ type: "contacts" })}><ShieldCheck size={26} /><span><strong>Perlu bantuan akses gerbang?</strong><small>Hubungi petugas keamanan. Gerbang dan kunci dikelola secara manual.</small></span><ArrowRight size={19} /></button>}</>;
}

function ResidentHome(a: Actions) {
  const portal = residentPortal(a.data);
  const accountName = portal.account?.name || "Warga";
  const feature = portalPosts(a.data, portal.account ? "resident" : "public")[0];
  const pending = portal.payments.filter(payment => payment.status === "pending").reduce((sum, payment) => sum + payment.amount, 0);
  return <><Heading eyebrow="D'PARK CITY" title={`Selamat datang, ${accountName.split(" ")[0]}`} subtitle="Tagihan, hunian, dan layanan lingkungan dalam satu tempat." />
    {!portal.canViewUnit && <div className="resident-pending-banner"><House size={21} /><div><strong>Hubungan hunian perlu diperbarui</strong><p>Hubungi pengurus untuk memeriksa data hunian. Tagihan atas nama Anda tetap tersedia.</p></div><Button secondary onClick={() => a.open({ type: "contacts" })}>Hubungi pengurus</Button></div>}
    <div className="resident-home-grid"><section className="resident-bill-hero"><div className="hero-small-label"><span><Wallet size={18} />Ringkasan tagihan</span><span>Unit {portal.unit?.number || "—"}</span></div><span className="resident-balance-label">Sisa pembayaran Anda</span><strong>{currency(portal.outstanding)}</strong><p>{pending > 0 ? `${currency(pending)} sedang menunggu verifikasi pengurus.` : portal.outstanding === 0 ? "Semua tagihan sudah lunas. Terima kasih atas kontribusi Anda." : `${portal.invoices.filter(invoice => remaining(invoice) > 0).length} tagihan belum lunas · Iuran dan air dari seluruh periode`}</p><div><Button onClick={() => a.go("invoices")}>Lihat semua tagihan <ArrowRight size={16} /></Button><span><ShieldCheck size={14} />Saldo mengikuti pembayaran terverifikasi</span></div></section>
    <button className="resident-unit-card panel" aria-label="Lihat data unit saya" onClick={() => a.go("unit")}><span className="unit-roof-icon"><House size={36} /></span><span className="eyebrow">HUNIAN SAYA</span><h2>{portal.unit ? `${portal.unit.cluster} / ${portal.unit.number}` : "Belum terhubung"}</h2><span className="muted">D&apos;Park City</span><div><Badge>{portal.canViewUnit ? portal.unit?.occupied ? "Terhuni" : "Kosong" : "Perlu pembaruan"}</Badge><span className="text-button">Lihat unit <ArrowRight size={14} /></span></div></button></div>
    <div className="section-title"><h2>Layanan untuk Anda</h2><button className="text-button" onClick={() => a.go("services")}>Semua layanan <ArrowRight size={15} /></button></div><div className="resident-quick-services">{[{ icon: FileCheck2, label: "Ajukan surat", kind: "letter" }, { icon: MessageCircle, label: "Laporkan lingkungan", kind: "report" }, { icon: UsersRound, label: "Laporkan tamu", kind: "guest" }, { icon: ShieldCheck, label: "Kontak keamanan", kind: "contacts" }].map(item => <button key={item.kind} disabled={item.kind !== "contacts" && !portal.canViewUnit} onClick={() => item.kind === "contacts" ? a.open({ type: "contacts" }) : a.open({ type: "requestForm", kind: item.kind as Request["kind"] })}><span><item.icon size={23} /></span><strong>{item.label}</strong></button>)}</div>
    <div className="section-title"><h2>Kabar lingkungan</h2><button className="text-button" onClick={() => a.go("news")}>Lihat semua <ArrowRight size={15} /></button></div>{feature ? <div className="resident-news-feature"><PostPicture post={feature} /><div><span className="news-category">{feature.category}</span><h2>{feature.title}</h2><p>{feature.body.slice(0, 150)}{feature.body.length > 150 ? "…" : ""}</p><button className="text-button" onClick={() => a.open({ type: "post", id: feature.id })}>Baca selengkapnya <ArrowRight size={16} /></button></div></div> : <Empty title="Kabar lingkungan segera hadir" detail="Berita dan kegiatan dari pengurus akan muncul di sini." />}
    <div className="section-title"><h2>Pengajuan terbaru</h2><button className="text-button" onClick={() => a.go("services")}>Lihat pengajuan <ArrowRight size={15} /></button></div><section className="panel simple-list">{portal.requests.slice(0, 2).map(request => <button key={request.id} onClick={() => a.open({ type: "request", id: request.id })}><span className="request-icon"><FileText size={21} /></span><span><strong>{request.title}</strong><small>{displayDate(request.date)}</small></span><Badge>{requestLabels[request.status]}</Badge><ChevronRight size={17} /></button>)}{!portal.requests.length && <Empty title="Belum ada pengajuan" detail="Surat, laporan, dan kunjungan yang Anda ajukan akan tampil di sini." />}</section></>;
}
function ResidentUnitView(a: Actions) {
  const portal = residentPortal(a.data);
  return <><Heading title="Unit saya" subtitle="Data hunian yang terhubung dengan akun Anda."><Button secondary onClick={() => a.open({ type: "contacts" })}><Phone size={16} />Minta pembaruan data</Button></Heading>{portal.canViewUnit && portal.unit ? <UnitDetails {...a} unit={portal.unit} resident /> : <section className="panel"><Empty title="Hubungan hunian perlu diperbarui" detail="Data penghuni saat ini tidak ditampilkan karena akun Anda belum terhubung sebagai pemilik atau penghuni aktif."><Button onClick={() => a.open({ type: "contacts" })}>Hubungi pengurus</Button><Button secondary onClick={() => a.go("invoices")}>Lihat tagihan atas nama saya</Button></Empty></section>}</>;
}

function ResidentAccount(a: Actions & { signout: () => void }) {
  const portal = residentPortal(a.data); const account = portal.account;
  const wa = account?.whatsappReminders ?? true;
  return <><Heading title="Akun saya" subtitle="Informasi akun dan preferensi komunikasi Anda." /><section className="panel account-panel"><Person name={account?.name || "Akun warga tidak aktif"} sub={`Warga D'Park City · Unit ${portal.unit?.number || "Belum terhubung"}`} /><hr /><div className="detail-grid"><Detail label="Identitas masuk" value={account?.contact || "Belum diisi"} /><Detail label="Nomor telepon" value={portal.phone || "Belum diisi pengurus"} /><Detail label="Hubungan hunian" value={portal.owner ? "Pemilik unit" : portal.occupant ? "Penghuni aktif" : "Perlu pembaruan oleh pengurus"} /><Detail label="Status akun" value={account ? "Aktif · Dikelola administrator" : "Tidak aktif"} /></div><div className="setting-row"><div><strong>Pengingat melalui WhatsApp</strong><p>Preferensi untuk pengingat tagihan yang disiapkan pengurus.</p></div><button className={`switch ${wa ? "on" : ""}`} role="switch" aria-checked={wa} aria-label="Izinkan pengingat WhatsApp" disabled={!account} onClick={() => { a.save(setResidentWhatsAppPreference(a.data, !wa)); a.notify(wa ? "Preferensi tersimpan: pengingat WhatsApp dinonaktifkan." : "Preferensi tersimpan: pengingat WhatsApp diaktifkan."); }}><span /></button></div><div className="row-actions"><Button secondary onClick={() => a.open({ type: "changePassword" })}>Ubah kata sandi</Button><Button secondary onClick={() => a.open({ type: "contacts" })}><Phone size={16} />Perbarui kontak melalui pengurus</Button><button className="text-button red-text" onClick={a.signout}><LogOut size={16} />Keluar</button></div></section></>;
}

function SettingsView(a: Actions) { return <><Heading title="Pengaturan lingkungan" subtitle="Informasi lingkungan, petugas, dan kebutuhan operasional." /><section className="panel settings-panel"><form onSubmit={e => { e.preventDefault(); a.notify("Pengaturan contoh tersimpan. Tidak ada perubahan pada lingkungan produksi."); }}><h2>Profil lingkungan</h2><p className="muted">Identitas yang terlihat oleh warga dan pengunjung.</p><div className="form-grid"><Field label="Nama lingkungan"><input defaultValue="D'Park City" required /></Field><Field label="Nama platform"><input defaultValue="Proomahan" readOnly /></Field><Field label="Bahasa"><select defaultValue="Bahasa Indonesia"><option>Bahasa Indonesia</option></select></Field><Field label="Zona waktu"><select defaultValue="Asia/Jakarta"><option>Asia/Jakarta</option></select></Field></div><hr /><h2>Instruksi pembayaran contoh</h2><div className="form-grid"><Field label="Nama bank"><input defaultValue="Bank contoh" required /></Field><Field label="Nomor rekening"><input defaultValue="0000 0000 0000" required /></Field><Field label="Atas nama"><input defaultValue="Kas lingkungan — data contoh" required /></Field><Field label="Penerima tunai"><input defaultValue="Petugas kas contoh" required /></Field></div><div className="form-footer"><Button type="submit"><Check size={16} />Simpan pengaturan</Button></div></form></section><section className="panel reset-panel"><div><h2>Mulai ulang pratinjau</h2><p>Kembalikan semua data contoh ke kondisi awal.</p></div><Button secondary onClick={() => a.open({ type: "resetDemo" })}>Atur ulang data contoh</Button></section></>; }

function PublicView(a: Actions & { enter: () => void }) { return <div className="public-page"><header className="public-header"><a href="#tentang" aria-label="Halaman utama Proomahan"><Logo /></a><nav><a href="#tentang">Lingkungan kita</a><a href="#kabar">Kabar warga</a><button onClick={() => a.open({ type: "contacts" })}>Kontak</button></nav><Button onClick={a.enter}><span className="desktop-label">Masuk sebagai warga</span><span className="mobile-label">Masuk</span><ArrowRight size={16} /></Button></header><main id="main-content" tabIndex={-1}><section className="public-hero" id="tentang"><div className="public-hero-copy"><span className="location-pill"><MapPin size={14} />D&apos;PARK CITY</span><h1>Rumah yang nyaman.<br />Lingkungan yang<br /><em>kita rawat bersama.</em></h1><p>Satu ruang untuk kabar lingkungan, kebutuhan warga, dan urusan hunian. Lebih dekat dengan tetangga, lebih mudah dengan Proomahan.</p><div><Button onClick={a.enter}>Masuk ke portal warga <ArrowRight size={17} /></Button><button className="text-button" onClick={() => a.open({ type: "contacts" })}>Hubungi pengurus</button></div><span className="hero-trust"><ShieldCheck size={17} />Akses warga dikelola langsung oleh pengurus lingkungan.</span></div><div className="public-hero-art"><Landscape hero /><div className="floating-neighborhood"><span className="neighborhood-icon"><Trees size={24} /></span><div><strong>D&apos;Park City</strong><span>Tempat pulang. Ruang bertumbuh.</span></div></div></div></section><section className="public-benefits"><div><FileText size={24} /><span><strong>Urusan iuran lebih jelas</strong><p>Rincian tagihan dan riwayat pembayaran dalam satu tempat.</p></span></div><div><MessageCircle size={24} /><span><strong>Pengurus lebih mudah dijangkau</strong><p>Sampaikan kebutuhan dan pantau tindak lanjutnya.</p></span></div><div><Leaf size={24} /><span><strong>Kabar lingkungan lebih dekat</strong><p>Ikuti informasi dan kegiatan bersama warga.</p></span></div></section><section className="public-news" id="kabar"><div className="section-title"><div><span className="eyebrow">DARI LINGKUNGAN KITA</span><h2>Kabar D&apos;Park City</h2></div><span className="subtle-chip">Informasi publik</span></div><div className="news-grid">{portalPosts(a.data, "public").map(p => <button className="news-card" key={p.id} onClick={() => a.open({ type: "post", id: p.id })}><PostPicture post={p} /><div className="news-card-copy"><span className="news-category">{p.category}</span><h2>{p.title}</h2><p>{p.body.slice(0, 110)}{p.body.length > 110 ? "…" : ""}</p><div><span>{displayDate(p.date)}</span><ArrowUpRight size={18} /></div></div></button>)}</div>{!portalPosts(a.data, "public").length && <Empty title="Kabar publik segera hadir" detail="Informasi lingkungan yang dibagikan untuk umum akan tampil di sini." />}</section><section className="public-cta"><Trees size={38} /><h2>Sudah menjadi warga D&apos;Park City?</h2><p>Masuk dengan akun yang diberikan pengurus untuk mengakses layanan warga.</p><Button onClick={a.enter}>Buka portal warga <ArrowRight size={16} /></Button></section></main><footer className="public-footer"><Logo /><span>D&apos;Park City · Pratinjau dengan data contoh</span><button className="text-button" onClick={() => a.open({ type: "contacts" })}>Kontak pengurus <ArrowUpRight size={15} /></button></footer></div>; }


function Modal({ title, subtitle, close, children, wide = false }: { title: string; subtitle?: string; close: () => void; children: ReactNode; wide?: boolean }) { const ref = useRef<HTMLDialogElement>(null); useEffect(() => { const dialog = ref.current!; dialog.showModal(); return () => { if (dialog.open) dialog.close(); }; }, []); return <dialog ref={ref} className={`modal ${wide ? "wide" : ""}`} onCancel={close} onClick={e => { if (e.target === ref.current) close(); }} aria-labelledby="modal-title"><div className="modal-heading"><div><h2 id="modal-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" aria-label="Tutup dialog" onClick={close}><X size={20} /></button></div>{children}</dialog>; }

function ModalContent(a: Actions & { spec: NonNullable<ModalSpec>; close: () => void; resident: boolean; publicView: boolean; actorId: string; at: string; onPeriodChange: (period: string) => void }) {
  const { spec, close } = a;
  const [error, setError] = useState("");
  const [step, setStep] = useState(0);
  const [method, setMethod] = useState("Transfer bank");
  const [period, setPeriod] = useState(spec.period || "2026-12");
  const [generateUnit, setGenerateUnit] = useState(spec.id || a.data.units[0]?.id || "");
  const [generateScope, setGenerateScope] = useState<BillingScope>(spec.id ? "individual" : "period");
  const [selectedUnits, setSelectedUnits] = useState<string[]>([]);
  const [temporary, setTemporary] = useState("");
  const [newsImage, setNewsImage] = useState("");
  const [newsBusy, setNewsBusy] = useState(false);
  const [rejection, setRejection] = useState("");
  const form = (event: FormEvent<HTMLFormElement>, callback: (fields: FormData) => void) => { event.preventDefault(); setError(""); try { callback(new FormData(event.currentTarget)); } catch (e) { setError(e instanceof Error ? e.message : "Periksa kembali data yang dimasukkan."); } };
  const finish = (next: Demo, message: string) => { a.save(next); close(); a.notify(message); };
  const errorBox = error && <div className="form-error" role="alert">{error}</div>;
  const foot = (label: string) => <div className="form-footer"><Button secondary onClick={close}>Batal</Button><Button type="submit">{label}<ArrowRight size={16} /></Button></div>;
  const portal = residentPortal(a.data);
  const publicAllowed = ["contacts", "help"].includes(spec.type) || spec.type === "post" && portalPosts(a.data, "public").some(post => post.id === spec.id);
  if (a.resident && !residentModalAllowed(a.data, spec) || a.publicView && !publicAllowed) return <Modal title="Informasi tidak tersedia" close={close}><div className="modal-body"><Empty title="Halaman ini tidak tersedia untuk akun Anda" detail="Kembali ke halaman utama atau hubungi pengurus untuk memeriksa hubungan hunian Anda." /><Button secondary onClick={close}>Kembali</Button></div></Modal>;
  if ((spec.type === "createBilling" || spec.type === "billingDetail") && !a.resident) { const selectedPeriod = spec.period || "2026-11"; return <Modal title={spec.type === "createBilling" ? "Pilih jenis tagihan" : "Detail tagihan warga"} subtitle={spec.id ? `Unit ${spec.id} · ${periodLabel(selectedPeriod)}` : periodLabel(selectedPeriod)} close={close}><InvoiceKindChooser initialKind={spec.billKind} data={a.data} unitId={spec.id} period={selectedPeriod} intent={spec.intent || "detail"} createMode={spec.type === "createBilling"} onCreate={kind => { if (kind === "dues") a.open({ type: "generate", id: spec.id, period: selectedPeriod }); else { const unitId = spec.id || waterOverview(a.data, selectedPeriod).rows.find(row => !row.invoice)?.unit.id || a.data.units[0]?.id; a.open({ type: "waterBill", id: unitId, period: selectedPeriod, scope: spec.id ? "individual" : "period" }); } }} onInvoice={invoice => { const pending = a.data.payments.find(payment => payment.invoiceId === invoice.id && payment.status === "pending"); a.open(spec.intent === "payment" ? pending ? { type: "review", id: pending.id } : { type: "adminPayment", id: invoice.id } : spec.intent === "reminder" ? { type: "reminder", id: invoice.id } : { type: "invoice", id: invoice.id }); }} /></Modal>; }
  if (spec.type === "waterBill" && !a.resident) return <Modal title="Buat tagihan air" subtitle="Isi meter, tarif, dan penanggung jawab untuk unit yang dipilih." close={close} wide><WaterBillForm data={a.data} save={a.save} actorId={a.actorId} at={a.at} notify={a.notify} initialUnit={spec.id || a.data.units[0]?.id || ""} initialPeriod={spec.period || "2026-12"} initialScope={spec.scope || "individual"} openInvoice={id => a.open({ type: "invoice", id })} cancel={close} onIssued={nextPeriod => { a.onPeriodChange(nextPeriod); close(); }} /></Modal>;
  if (spec.type === "clusters") return <Modal title="Kelola klaster" subtitle="Atur daftar klaster dan lihat keterhunian unit di lingkungan Anda." close={close} wide><ClusterManagement data={a.data} save={a.save} notify={a.notify} /></Modal>;
  if ((spec.type === "residentContacts" || spec.type === "occupancy") && !a.resident) { const unit = a.data.units.find(unit => unit.id === spec.id)!; const props = { data: a.data, unit, actorId: a.actorId, at: a.at, save: a.save, close, notify: a.notify }; return <Modal title={spec.type === "occupancy" ? unit.occupied ? "Check-out penghuni" : "Check-in penghuni" : "Edit data warga dan unit"} subtitle={`Unit ${unit.number} · ${unit.cluster}`} close={close} wide>{spec.type === "occupancy" ? <OccupancyForm {...props} /> : <ResidentContactForm {...props} />}</Modal>; }
  if (spec.type === "unit") { const unit = a.data.units.find(u => u.id === spec.id)!; return <Modal title={`Detail unit ${unit.number}`} close={close} wide><UnitDetails {...a} unit={unit} resident={a.resident} /></Modal>; }
  if (spec.type === "invoice") {
    const invoice = a.data.invoices.find(i => i.id === spec.id)!; const pending = a.data.payments.filter(p => p.invoiceId === invoice.id && p.status === "pending");
    return <Modal title="Rincian tagihan" subtitle={invoice.id} close={close}><div className="modal-body"><div className="invoice-detail-top"><div><span className="eyebrow">{invoice.period.toUpperCase()}</span><h3>Unit {invoice.unitNumber || invoice.unitId}</h3><p>Ditagihkan kepada {invoice.person}</p></div><Badge>{settlement(invoice)}</Badge></div><div className="invoice-summary-cards"><div><span>Total tagihan</span><strong>{currency(total(invoice))}</strong></div><div><span>Terverifikasi</span><strong>{currency(invoice.paid)}</strong></div><div><span>Sisa pembayaran</span><strong>{currency(remaining(invoice))}</strong></div></div><div className="detail-pair due-pair"><span>Jatuh tempo</span><strong>{displayDate(invoice.due)}</strong></div><h4 className="minor-heading">Rincian biaya</h4>{invoice.kind !== "water" && invoice.items.some(item => item.chargeType === "water") && <p className="billing-helper">Invoice gabungan iuran dan air. Pembayaran dan sisa dihitung satu kali untuk seluruh rincian.</p>}<div className="invoice-lines"><InvoiceItemStatus invoice={invoice} /></div>{pending.length > 0 && <div className="pending-note"><Clock3 size={20} /><div><strong>{currency(pending.reduce((s, p) => s + p.amount, 0))} menunggu verifikasi</strong><p>Sisa tagihan berubah setelah pengurus memverifikasi pembayaran.</p></div></div>}<details className="invoice-history"><summary>Riwayat konfirmasi ({a.data.payments.filter(p => p.invoiceId === invoice.id).length})</summary>{a.data.payments.filter(p => p.invoiceId === invoice.id).map(p => <div className="payment-history" key={p.id}><span><strong>{currency(p.amount)}</strong><small>{p.method} · {displayDate(p.date)}</small><PaymentAllocationHistory invoice={invoice} payment={p} />{p.origin === "admin" && <small>Dicatat pengurus: {a.data.accounts.find(u => u.id === p.recordedBy)?.name || "Pengurus"}</small>}{p.reason && <small>Alasan: {p.reason}</small>}</span><Badge>{paymentLabels[p.status]}</Badge></div>)}{!a.data.payments.some(p => p.invoiceId === invoice.id) && <p className="muted">Belum ada pengajuan konfirmasi pembayaran.</p>}</details></div><div className="modal-footer invoice-detail-footer"><InvoiceDownload invoice={invoice} notify={a.notify} />{a.resident ? remaining(invoice) > 0 && <Button disabled={pending.length > 0} onClick={() => a.open({ type: "submitPayment", id: invoice.id })}><Upload size={16} />{pending.length ? "Menunggu verifikasi" : "Konfirmasi mandiri"}</Button> : <div className="row-actions invoice-modal-actions"><Button secondary disabled={remaining(invoice) === 0 || pending.length > 0} onClick={() => a.open({ type: "reminder", id: invoice.id })}><MessageCircle size={16} />Pengingat WA</Button><Button disabled={remaining(invoice) === 0} onClick={() => a.open(pending[0] ? { type: "review", id: pending[0].id } : { type: "adminPayment", id: invoice.id })}><FileCheck2 size={16} />{pending.length ? "Tinjau pembayaran" : "Bantu konfirmasi"}</Button></div>}</div></Modal>;
  }
  if (spec.type === "adminPayment" && !a.resident) { const invoice = a.data.invoices.find(i => i.id === spec.id)!; return <Modal title="Konfirmasi dibantu pengurus" subtitle={`${invoice.id} · ${invoice.period}`} close={close}><AdminPaymentForm data={a.data} save={a.save} actorId={a.actorId} at={a.at} notify={a.notify} invoice={invoice} close={close} /></Modal>; }
  if (spec.type === "submitPayment") { const invoice = a.data.invoices.find(i => i.id === spec.id)!; return <Modal title="Konfirmasi mandiri warga" subtitle={`${invoice.period} · Unit ${invoice.unitNumber || invoice.unitId}`} close={close}><ResidentSelfAssessment data={a.data} save={a.save} at={a.at} notify={a.notify} invoice={invoice} close={close} /></Modal>; }
  if (spec.type === "review") { const payment = a.data.payments.find(p => p.id === spec.id)!; const invoice = a.data.invoices.find(i => i.id === payment.invoiceId)!; return <Modal title="Tinjau pembayaran" subtitle={`${payment.id} · ${invoice.id}`} close={close} wide><PaymentReview data={a.data} save={a.save} actorId={a.actorId} at={a.at} notify={a.notify} invoice={invoice} payment={payment} close={close} /></Modal>; }
  if (spec.type === "fee" || spec.type === "feeOverride") { const override = spec.type === "feeOverride"; const fee = a.data.fees.find(f => f.id === spec.id); return <Modal title={override ? "Buat tarif khusus" : fee ? "Ubah item biaya" : "Tambah item biaya"} subtitle="Atur biaya sesuai kesepakatan lingkungan." close={close}><form onSubmit={e => form(e, f => { validateFeeScope(a.data, String(f.get("scope")), override ? undefined : fee?.scope); const amount = Number(f.get("amount")); if (!Number.isSafeInteger(amount) || amount <= 0) throw new Error("Nominal harus berupa rupiah bulat dan lebih dari nol."); const next: Fee = { id: override ? uid() : fee?.id || uid(), itemId: fee?.itemId || fee?.id, effectiveFrom: String(f.get("startDate")), name: String(f.get("name")).trim(), category: String(f.get("category")).trim(), amount, frequency: String(f.get("frequency")), scope: String(f.get("scope")), payer: String(f.get("payer")), vacancy: String(f.get("vacancy")), active: fee?.active ?? true }; finish({ ...a.data, fees: fee && !override ? a.data.fees.map(x => x.id === fee.id ? next : x) : [...a.data.fees, next] }, "Item biaya tersimpan. Tagihan yang sudah terbit tidak berubah."); })}><div className="modal-body"><div className="form-grid"><Field label="Nama item biaya"><input name="name" defaultValue={fee?.name} placeholder="Contoh: Perawatan taman" required maxLength={70} /></Field><Field label="Kategori"><input name="category" defaultValue={fee?.category} list="fee-categories" placeholder="Pilih atau buat kategori" required /><datalist id="fee-categories">{[...new Set(a.data.fees.map(f => f.category))].map(c => <option key={c} value={c} />)}</datalist></Field><Field label="Nominal (Rp)"><input name="amount" type="number" min="1" step="1" defaultValue={fee?.amount || 50000} required /></Field><Field label="Frekuensi"><select name="frequency" defaultValue={fee?.frequency || "Bulanan"}><option>Bulanan</option><option>Satu kali</option></select></Field><Field label="Berlaku untuk"><select name="scope" defaultValue={override ? "A-12" : fee?.scope || "Semua unit"}><option>Semua unit</option>{a.data.clusters.filter(c => !c.archived || !override && fee?.scope === `Klaster ${c.name}`).map(c => <option key={c.id}>Klaster {c.name}</option>)}{a.data.units.map(u => <option key={u.id}>{u.id}</option>)}</select></Field><Field label="Penanggung jawab"><select name="payer" defaultValue={fee?.payer || "Penghuni utama"}><option>Penghuni utama</option><option>Pemilik utama</option></select></Field><Field label="Jika unit kosong"><select name="vacancy" defaultValue={fee?.vacancy || "Tidak ditagih"}><option>Tidak ditagih</option><option>Tetap ditagih</option></select></Field><Field label="Tanggal mulai"><input name="startDate" type="date" defaultValue={fee?.effectiveFrom || "2026-12-01"} required /></Field></div><div className="info-note"><FileText size={18} />Pengaturan berlaku mulai tanggal yang dipilih. Tarif khusus menggantikan tarif umum untuk item yang sama. Nilai pada tagihan yang sudah terbit tetap.</div>{errorBox}</div>{foot("Simpan item biaya")}</form></Modal>; }
  if (spec.type === "generate") { let preview: Invoice[] = []; let previewError = ""; try { preview = previewInvoices(a.data, periodLabel(period)).filter(invoice => scopedUnitIds(a.data, generateScope, selectedUnits, generateUnit).includes(invoice.unitId)); } catch (e) { previewError = (e as Error).message; } return <Modal title="Buat tagihan iuran" subtitle="Periksa rincian sebelum tagihan diterbitkan." close={close} wide><div className="modal-body"><div className="generation-controls"><Field label="Periode tagihan iuran"><input type="month" min="2000-01" max="2099-12" required value={period} onChange={e => { if (/^20\d{2}-(0[1-9]|1[0-2])$/.test(e.target.value)) setPeriod(e.target.value); }} /></Field><span className="subtle-chip"><Eye size={15} />Pratinjau sebelum terbit</span></div><BillingScopePicker units={a.data.units} scope={generateScope} setScope={setGenerateScope} selected={selectedUnits} setSelected={setSelectedUnits} individual={generateUnit} setIndividual={setGenerateUnit} /><div className="preview-summary"><div><span>Tagihan baru</span><strong>{preview.length}</strong></div><div><span>Total nominal</span><strong>{currency(preview.reduce((s, i) => s + total(i), 0))}</strong></div><div><span>Item aktif</span><strong>{new Set(a.data.fees.filter(f => f.active).map(f => f.itemId || f.id)).size}</strong></div></div>{previewError && <div role="alert" className="form-error">{previewError}</div>}{!preview.length && !previewError ? <Empty title="Tidak ada tagihan baru" detail="Semua unit untuk periode ini sudah ditagih. Sistem mencegah tagihan ganda." /> : <div className="preview-table table-scroll"><table><thead><tr><th>Unit</th><th>Penanggung jawab</th><th>Item</th><th>Nominal</th></tr></thead><tbody>{preview.map(i => <tr key={i.id}><td><strong>{i.unitNumber || i.unitId}</strong></td><td>{i.person}</td><td>{i.items.length} item biaya</td><td>{currency(total(i))}</td></tr>)}</tbody></table></div>}<div className="info-note"><ShieldCheck size={18} />Pratinjau menggunakan konfigurasi item biaya saat ini. Data ini merupakan simulasi.</div></div><div className="modal-footer"><Button secondary onClick={close}>Batal</Button><Button disabled={!preview.length || !!previewError} onClick={() => { try { const fresh = previewInvoices(a.data, periodLabel(period)).filter(invoice => scopedUnitIds(a.data, generateScope, selectedUnits, generateUnit).includes(invoice.unitId)); if (!fresh.length) throw new Error("Tagihan sudah tersedia."); a.onPeriodChange(period); finish({ ...a.data, invoices: [...a.data.invoices, ...fresh] }, `${fresh.length} tagihan contoh berhasil diterbitkan.`); } catch (e) { setError((e as Error).message); } }}><Check size={16} />Terbitkan {preview.length} tagihan</Button></div>{errorBox}</Modal>; }
  if (spec.type === "expenseMessage" || spec.type === "cashMessage") { const entry = a.data.cashEntries.find(e => e.id === spec.id); const summary = cashSummary(a.data, spec.type === "cashMessage" ? spec.id! : entry!.date.slice(0, 7)); const message = entry ? renderMessage(a.data, "expense", { tanggal: displayDate(entry.date), kategori: entry.category, nominal: currency(entry.amount), catatan: entry.note }) : renderMessage(a.data, "cash_report", { periode: spec.id!, saldo_awal: currency(summary.opening), pemasukan: currency(summary.income), pengeluaran: currency(summary.expenses), saldo_akhir: currency(summary.closing) }); return <Modal title="Pratinjau laporan WhatsApp" close={close}><MessagePreview initialMessage={message} close={close} /></Modal>; }
  if (spec.type === "reminder") { const invoice = a.data.invoices.find(i => i.id === spec.id)!; return <Modal title="Pengingat tagihan WhatsApp" subtitle={`${invoice.person} · Unit ${invoice.unitNumber || invoice.unitId}`} close={close}><ReminderTemplate data={a.data} invoice={invoice} close={close} /></Modal>; }
  if (spec.type === "addUnit") return <Modal title="Tambah unit" subtitle="Catat unit dan pemilik dalam lingkungan D'Park City." close={close}><form onSubmit={e => form(e, f => { const number = String(f.get("number")).trim().toUpperCase(); if (a.data.units.some(u => u.id === number)) throw new Error("Nomor unit sudah digunakan."); const unit: Unit = { id: number, number, cluster: String(f.get("cluster")), owner: String(f.get("owner")).trim(), occupant: String(f.get("occupant") || "").trim(), occupied: !!String(f.get("occupant") || "").trim(), tenure: String(f.get("tenure")), forRent: f.get("forRent") === "yes" || String(f.get("tenure")) === "Disewakan", since: a.at.slice(0, 10) }; const contacts = residentContacts({ ownerPhone: String(f.get("ownerPhone") || ""), ownerDocumentsUrl: String(f.get("ownerDocumentsUrl") || ""), occupantPhone: String(f.get("occupantPhone") || ""), occupantDocumentsUrl: String(f.get("occupantDocumentsUrl") || "") }, unit); finish(addUnit(a.data, { ...unit, ...contacts }), "Unit contoh berhasil ditambahkan."); })}><div className="modal-body"><div className="form-grid"><Field label="Nomor unit"><input name="number" placeholder="Contoh: A-17" required maxLength={12} /></Field><Field label="Klaster"><select name="cluster" required><option value="" disabled>Pilih klaster aktif</option>{a.data.clusters.filter(c => !c.archived).map(c => <option key={c.id} value={c.name}>{c.name}</option>)}</select></Field><Field label="Nama pemilik"><input name="owner" placeholder="Nama pemilik contoh" required /></Field><Field label="Nomor telepon pemilik"><input name="ownerPhone" type="tel" required maxLength={25} placeholder="Contoh: +6281234567890" /></Field><Field label="URL dokumen pemilik (opsional)"><input name="ownerDocumentsUrl" type="url" maxLength={2000} placeholder="https://drive.google.com/drive/folders/..." /></Field><Field label="Penghuni utama (opsional)"><input name="occupant" placeholder="Kosongkan jika belum dihuni" /></Field><Field label="Nomor telepon penghuni"><input name="occupantPhone" type="tel" maxLength={25} placeholder="Isi jika penghuni berbeda dengan pemilik" /></Field><Field label="URL dokumen penghuni (opsional)"><input name="occupantDocumentsUrl" type="url" maxLength={2000} placeholder="https://drive.google.com/drive/folders/..." /></Field><Field label="Rumah untuk disewakan"><select name="forRent"><option value="no">Tidak</option><option value="yes">Ya</option></select></Field><Field label="Tipe hunian"><select name="tenure"><option>Dihuni pemilik</option><option>Disewakan</option></select></Field></div>{errorBox}</div>{foot("Simpan unit")}</form></Modal>;
  if (spec.type === "account" || spec.type === "resetPassword") { const account = a.data.accounts.find(u => u.id === spec.id); return <Modal title={temporary ? "Kata sandi sementara" : account ? "Atur ulang kata sandi" : "Buat akun pengguna"} subtitle={account ? account.name : "Akun dan akses disetujui langsung oleh administrator."} close={close}>{temporary ? <div className="modal-body"><div className="success-circle"><Check size={27} /></div><h3 className="center">Akun contoh siap digunakan</h3><p className="muted center">Kata sandi ini hanya untuk simulasi, bukan kredensial akun sungguhan.</p><div className="temporary-password">{temporary}</div><div className="info-note">Pada aplikasi sebenarnya, warga harus mengganti kata sandi sementara saat pertama masuk.</div><div className="form-footer"><Button onClick={close}>Selesai <Check size={16} /></Button></div></div> : <form onSubmit={e => form(e, f => { if (!account) { const next: Account = { id: uid(), name: String(f.get("name")).trim(), contact: String(f.get("contact")).trim(), unit: String(f.get("unit")), resident: true, active: true }; if (a.data.accounts.some(u => u.contact.toLowerCase() === next.contact.toLowerCase())) throw new Error("Nomor telepon atau email sudah digunakan oleh akun contoh lain."); a.save({ ...a.data, accounts: [...a.data.accounts, next] }); } setTemporary("ContohBaru2026!"); })}><div className="modal-body">{account ? <div className="info-note"><ShieldCheck size={18} />Pastikan identitas warga sebelum mengatur ulang sandi. Ini hanya simulasi; akun autentikasi sungguhan tidak diubah.</div> : <div className="form-grid"><Field label="Nama lengkap"><input name="name" required placeholder="Nama pengguna contoh" /></Field><Field label="Nomor telepon"><input name="contact" required placeholder="warga@example.test" /></Field><Field label="Unit terkait"><select name="unit"><option value="—">Tidak terhubung ke unit</option>{a.data.units.map(u => <option key={u.id}>{u.id}</option>)}</select></Field><div className="info-note">Akun baru memiliki akses warga sesuai hubungan hunian. Super Administrator menetapkan peran pengurus secara terpisah di menu Peran dan masa jabatan.</div></div>}{errorBox}</div>{foot(account ? "Buat sandi sementara" : "Buat akun contoh")}</form>}</Modal>; }
  if (spec.type === "requestForm") { const kind = spec.kind || "letter"; const titles = { letter: "Ajukan surat warga", report: "Kirim permintaan layanan", guest: "Laporkan kunjungan tamu" }; return <Modal title={titles[kind]} subtitle={`Unit ${portal.unit?.number || "—"} · ${portal.account?.name || "Warga"}`} close={close}><form onSubmit={e => form(e, f => { if (!portal.canViewUnit || !portal.account || !portal.unit) throw new Error("Hubungi pengurus untuk memperbarui hubungan hunian sebelum mengajukan layanan."); const request: Request = { id: `${kind === "letter" ? "SR" : kind === "report" ? "LP" : "TM"}-${uid().slice(0, 5).toUpperCase()}`, kind, title: String(f.get("title")), person: portal.account!.name, unitId: portal.unit!.id, detail: `${String(f.get("detail"))}${kind === "guest" ? ` · ${f.get("visitDate")} ${f.get("timeFrom")}–${f.get("timeUntil")}` : ""}`, date: "7 Nov 2026", status: "submitted", events: ["7 Nov · Pengajuan diterima"] }; if (kind === "guest" && String(f.get("timeUntil")) <= String(f.get("timeFrom"))) throw new Error("Waktu selesai kunjungan harus setelah waktu mulai."); finish({ ...a.data, requests: [request, ...a.data.requests] }, "Pengajuan contoh diterima. Pantau perkembangannya di Layanan."); })}><div className="modal-body">{kind === "letter" ? <Field label="Jenis surat"><select name="title"><option>Surat keterangan domisili</option><option>Surat pengantar</option><option>Surat pindah masuk</option><option>Surat pindah keluar</option></select></Field> : <Field label={kind === "guest" ? "Nama tamu / keperluan" : "Judul permintaan"}><input name="title" placeholder={kind === "guest" ? "Contoh: Kunjungan keluarga — Rudi" : "Contoh: Lampu jalan padam"} required maxLength={100} /></Field>}{kind === "guest" && <><Field label="Tanggal kunjungan"><input name="visitDate" type="date" defaultValue="2026-11-08" required /></Field><div className="form-grid"><Field label="Mulai"><input name="timeFrom" type="time" defaultValue="10:00" required /></Field><Field label="Selesai"><input name="timeUntil" type="time" defaultValue="14:00" required /></Field></div></>}<Field label={kind === "letter" ? "Keperluan surat" : kind === "guest" ? "Catatan / kendaraan (opsional)" : "Rincian dan lokasi"}><textarea name="detail" rows={4} required={kind !== "guest"} placeholder="Tuliskan informasi agar pengurus dapat membantu..." /></Field>{kind !== "guest" && <Field label="Lampiran contoh (opsional)"><input type="file" accept="image/*,application/pdf" /></Field>}<div className="info-note"><ShieldCheck size={18} />{kind === "guest" ? "Laporan memberi tahu petugas tentang kunjungan. Akses gerbang tetap diatur secara manual." : "Pengajuan hanya terlihat oleh Anda dan pengurus yang berwenang."}</div>{errorBox}</div>{foot("Kirim pengajuan")}</form></Modal>; }
  if (spec.type === "request") { const request = a.data.requests.find(r => r.id === spec.id)!; const update = (status: string, label: string) => finish({ ...a.data, requests: a.data.requests.map(r => r.id === request.id ? { ...r, status, events: [...r.events, `7 Nov · ${label}`], ...(status === "issued" ? { reference: `DPC/SR/2026/${r.id}`, file: "surat-contoh.pdf" } : {}) } : r) }, `Status diperbarui: ${label.toLowerCase()}.`); return <Modal title={request.title} subtitle={`${request.id} · ${request.person} · Unit ${request.unitId}`} close={close}><div className="modal-body"><Badge>{requestLabels[request.status]}</Badge><p className="request-description">{request.detail}</p>{request.reference && <div className="bank-instructions"><span>NOMOR SURAT</span><strong>{request.reference}</strong><small>{request.file} · Dokumen simulasi</small></div>}<h4 className="minor-heading">Perkembangan pengajuan</h4><div className="timeline">{request.events.map((event, i) => <div key={i}><i /><strong>{event}</strong></div>)}</div>{a.resident && request.status === "needs_revision" && <form onSubmit={e => form(e, f => { finish({ ...a.data, requests: a.data.requests.map(r => r.id === request.id ? { ...r, detail: String(f.get("revision")), status: "submitted", events: [...r.events, "7 Nov · Perbaikan dikirim warga"] } : r) }, "Perbaikan pengajuan berhasil dikirim."); })}><Field label="Perbaiki rincian"><textarea name="revision" defaultValue={request.detail} required /></Field><Button type="submit">Kirim perbaikan</Button></form>}{!a.resident && request.kind === "letter" && request.status === "approved" && <Field label="Unggah surat bertanda tangan (PDF contoh)"><input type="file" accept="application/pdf" onChange={e => { if (e.target.files?.length) setStep(1); }} /></Field>}<div className="info-note">{a.resident ? "Pengurus akan memperbarui status setelah meninjau pengajuan Anda." : "Pembaruan status ini merupakan simulasi untuk meninjau alur layanan."}</div></div><div className="modal-footer">{a.resident ? <Button secondary onClick={close}>Tutup</Button> : <>{request.status === "submitted" && <Button onClick={() => update(request.kind === "guest" ? "acknowledged" : "under_review", request.kind === "guest" ? "Diketahui petugas" : "Sedang diproses")}>{request.kind === "guest" ? "Tandai diketahui" : "Mulai proses"}<ArrowRight size={16} /></Button>}{request.status === "under_review" && <><Button secondary onClick={() => update("needs_revision", "Perlu perbaikan rincian pengajuan")}>Minta perbaikan</Button><Button onClick={() => update(request.kind === "letter" ? "approved" : "resolved", request.kind === "letter" ? "Disetujui pengurus" : "Permintaan selesai")}><Check size={16} />{request.kind === "letter" ? "Setujui pengajuan" : "Tandai selesai"}</Button></>}{request.status === "approved" && request.kind === "letter" && <Button disabled={!step} onClick={() => update("issued", "Surat terbit dan tersedia untuk warga")}><FileCheck2 size={16} />Terbitkan surat contoh</Button>}{["issued", "resolved", "acknowledged", "needs_revision"].includes(request.status) && <Button secondary onClick={close}>Tutup</Button>}</>}</div></Modal>; }
  if (spec.type === "contacts") return <Modal title="Kontak layanan lingkungan" subtitle="Petugas dan pengurus D'Park City." close={close}><div className="modal-body contacts-list">{[{ icon: ShieldCheck, title: "Keamanan dan gerbang", time: "Petugas jaga · 24 jam", desc: "Bantuan akses gerbang dan keamanan lingkungan." }, { icon: UsersRound, title: "Administrasi lingkungan", time: "Senin–Jumat · 09.00–17.00", desc: "Akun warga, data hunian, dan pengajuan surat." }, { icon: Wallet, title: "Petugas penagihan", time: "Senin–Sabtu · 09.00–16.00", desc: "Tagihan, penerimaan tunai, dan konfirmasi pembayaran." }].map(c => <div key={c.title} className="contact-card"><span className="attention-icon teal"><c.icon size={23} /></span><div><h3>{c.title}</h3><small>{c.time}</small><p>{c.desc}</p><button className="text-button" onClick={() => a.notify("Pratinjau kontak saja. Nomor petugas akan diisi pengurus sebelum peluncuran.")}><Phone size={14} />Lihat kontak contoh <ArrowUpRight size={14} /></button></div></div>)}<div className="info-note"><Fence size={18} />Pembukaan gerbang dan penggunaan kunci ditangani petugas secara manual.</div></div></Modal>;
  if (spec.type === "post") { const post = a.data.posts.find(p => p.id === spec.id)!; return <Modal title="Kabar lingkungan" subtitle={`${post.category} · ${displayDate(post.date)}`} close={close}><PostPicture post={post} /><article className="modal-body post-body"><Badge tone="teal">{post.audience}</Badge><h2>{post.title}</h2><p>{post.body}</p><small className="muted">Diterbitkan oleh pengurus D&apos;Park City · Data contoh</small></article></Modal>; }
  if (spec.type === "addPost") return <Modal title="Tulis berita lingkungan" subtitle="Pilih pembaca yang sesuai sebelum menerbitkan." close={close}><form onSubmit={e => form(e, f => { const post: Post = { id: uid(), title: String(f.get("title")).trim(), category: String(f.get("category")), audience: String(f.get("audience")), body: String(f.get("body")), date: "7 November 2026", art: "garden", ...(newsImage ? { image: newsImage } : {}) }; finish({ ...a.data, posts: [post, ...a.data.posts] }, "Berita contoh berhasil diterbitkan."); })}><div className="modal-body"><Field label="Judul berita"><input name="title" required maxLength={120} /></Field><div className="form-grid"><Field label="Kategori"><select name="category"><option>Kegiatan warga</option><option>Pengumuman</option><option>Agenda lingkungan</option></select></Field><Field label="Pembaca"><select name="audience"><option>Semua warga</option><option>Publik</option></select></Field></div><Field label="Isi berita"><textarea name="body" rows={6} required /></Field><div className="info-note">Berita untuk semua warga hanya muncul di ruang warga. Berita publik juga muncul di halaman lingkungan.</div><Field label="Gambar berita (opsional)" hint="JPG, PNG, atau WebP maksimal 2 MB; gambar diperkecil untuk pratinjau."><input type="file" accept="image/jpeg,image/png,image/webp" onChange={async e => { const file = e.target.files?.[0]; setNewsImage(""); setError(""); if (!file) return; setNewsBusy(true); try { setNewsImage(await readNewsImage(file)); } catch (error) { setError(error instanceof Error ? error.message : "Gambar tidak dapat dibaca."); } finally { setNewsBusy(false); } }} /></Field>{newsBusy && <p role="status">Menyiapkan gambar...</p>}{newsImage && <div className="news-upload-preview"><img src={newsImage} alt="Pratinjau gambar berita" /><button type="button" className="text-button" onClick={() => setNewsImage("")}>Hapus gambar</button></div>}{errorBox}</div><div className="form-footer"><Button secondary onClick={close}>Batal</Button><Button type="submit" disabled={newsBusy}>Terbitkan berita</Button></div></form></Modal>;
  if (spec.type === "resetDemo") return <Modal title="Atur ulang data contoh?" subtitle="Perubahan selama pratinjau akan dikembalikan ke kondisi awal." close={close}><div className="modal-body"><p>Tagihan, item biaya, akun, berita, dan pengajuan contoh yang Anda buat akan dihapus dari penyimpanan pratinjau browser ini.</p></div><div className="modal-footer"><Button secondary onClick={close}>Batal</Button><Button onClick={() => finish(createDemo(), "Data contoh dikembalikan ke kondisi awal.")}>Atur ulang</Button></div></Modal>;
  if (spec.type === "notifications") return <Modal title="Pemberitahuan" subtitle="Ringkasan aktivitas lingkungan contoh." close={close}><div className="modal-body simple-list">{[{ label: `${(a.resident ? portal.payments : a.data.payments).filter(p => p.status === "pending").length} pembayaran menunggu verifikasi`, view: "payments", icon: Wallet }, { label: a.resident ? `${portal.requests.filter(request => !["issued", "resolved", "acknowledged"].includes(request.status)).length} pengajuan Anda sedang diproses` : "Pengajuan layanan warga perlu ditinjau", view: "services", icon: MessageCircle }, { label: "Kabar terbaru dari lingkungan", view: "news", icon: Newspaper }].map(n => <button key={n.view} onClick={() => { close(); a.go(a.resident && n.view === "payments" ? "invoices" : n.view); }}><n.icon size={20} /><span><strong>{n.label}</strong><small>7 November 2026 · Data contoh</small></span><ChevronRight size={16} /></button>)}</div></Modal>;
  if (spec.type === "changePassword") return <Modal title="Ubah kata sandi" subtitle="Simulasi perubahan kata sandi akun warga." close={close}><form onSubmit={e => form(e, f => { if (f.get("newPassword") !== f.get("confirmPassword")) throw new Error("Konfirmasi kata sandi belum sama."); close(); a.notify("Alur perubahan kata sandi selesai dalam pratinjau. Tidak ada kredensial sungguhan yang disimpan."); })}><div className="modal-body"><Field label="Kata sandi saat ini"><input type="password" required autoComplete="off" /></Field><Field label="Kata sandi baru"><input type="password" name="newPassword" minLength={8} required autoComplete="off" /></Field><Field label="Konfirmasi kata sandi baru"><input type="password" name="confirmPassword" minLength={8} required autoComplete="off" /></Field>{errorBox}</div>{foot("Simpan kata sandi")}</form></Modal>;
  return <Modal title={spec.type === "profile" ? "Profil administrator" : "Bantuan akun"} close={close}><div className="modal-body">{spec.type === "profile" && <Person name="Nadia Putri" sub="Administrator lingkungan · D'Park City" />}<p className="request-description">Akun dan akses warga dikelola oleh administrator lingkungan. Hubungi pengurus untuk pembuatan akun, perubahan identitas masuk, atau bantuan kata sandi.</p><div className="info-note"><CircleHelp size={18} />Ini adalah pratinjau interaktif. Seluruh nama, nominal, dokumen, dan aktivitas merupakan data contoh.</div><Button secondary onClick={() => a.open({ type: "contacts" })}>Lihat kontak pengurus <ArrowRight size={16} /></Button></div></Modal>;
}
